    15	  case "${1:-}" in
    16	    ''|.|..|lo|*[!ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-]*)
    17	      cleanup_fatal "invalid managed interface name"
    18	      ;;
