    24	  path_label=$1
    25	  path_value=$2
    26	
    27	  case "$path_value" in
    28	    /*) ;;
    29	    *) cleanup_fatal "${path_label} must be an absolute path" ;;
    30	  esac
    31	  case "$path_value" in
    32	    *[![:print:]]*|*[[:space:]]*)
    33	      cleanup_fatal "${path_label} contains unsupported characters"
    34	      ;;
    35	  esac
    36	  case "/${path_value#/}/" in
    37	    *"/../"*|*"/./"*|*"//"*)
    38	      cleanup_fatal "${path_label} contains an unsafe path component"
    39	      ;;
    40	  esac
    41	}
    42	
