    47	        or die "cannot read managed AppArmor event log: $path: $!\n";
    48	    binmode $fh, ':raw'
    49	        or die "cannot read managed AppArmor event log: $path: $!\n";
    50	
    51	    my (@records, @rejected);
    52	    my (%by_signature, $denial_count, $line_number);
    53	    while (my $line = <$fh>) {
    54	        ++$line_number;
    55	        length($line) <= $self->maximum_line_bytes()
    56	            or die "managed AppArmor event log line $line_number exceeds "
    57	                . $self->maximum_line_bytes() . " bytes\n";
    58	        next if index($line, 'apparmor="DENIED"') < 0;
    59	
    60	        ++$denial_count;
    61	        $denial_count <= $self->maximum_records()
    62	            or die "managed AppArmor event log contains more than "
    63	                . $self->maximum_records() . " denied records\n";
