   188	sub _decode_quoted {
   189	    my ($self, $value, $line_number, $field) = @_;
   190	
   191	    my $decoded = q{};
   192	    while (length($value)) {
   193	        if ($value =~ s/\A([^\\]+)//s) {
   194	            $decoded .= $1;
   195	            next;
   196	        }
