   202	            $decoded .= chr(oct($1));
   203	            next;
   204	        }
   205	        if ($value =~ s/\A\\([\\"])//) {
   206	            $decoded .= $1;
   207	            next;
   208	        }
   209	        die "AppArmor denial line $line_number has an unsupported escape in field $field\n";
   210	    }
   211	    $decoded !~ /[\x00\r\n]/
   212	        or die "AppArmor denial line $line_number contains a control character in field $field\n";
