   215	        if (my $label = $self->_profile_header($line, \@stack)) {
   216	            push @stack, $label;
   217	            next;
   218	        }
   219	        if ($line =~ /^\s*#?\s*include\s+if\s+exists\s+<local\/([A-Za-z0-9._+-]+)>\s*(?:#.*)?\z/) {
