   326	sub _prepare_backup_dir {
   327	    my ($self) = @_;
   328	
   329	    defined($self->backup_dir()) &&
   330	        $self->backup_dir() =~ m{\A/} &&
   331	        $self->backup_dir() ne '/' &&
   332	        index($self->backup_dir(), '..') < 0 &&
   333	        $self->backup_dir() !~ /[\r\n\0]/
   334	        or die "AppArmor rule backup directory must be a safe absolute path\n";
   335	    make_path($self->backup_dir(), { mode => 0700 })
   336	        if !-e $self->backup_dir();
   337	    my @metadata = lstat($self->backup_dir());
   338	    @metadata && ($metadata[2] & 0170000) == 0040000 &&
   339	        !-l $self->backup_dir()
   340	        or die "AppArmor rule backup directory must be a real directory\n";
   341	    $metadata[4] == $self->trusted_uid()
   342	        or die "AppArmor rule backup directory must be owned by the trusted account\n";
   343	    ($metadata[2] & 0077) == 0
   344	        or die "AppArmor rule backup directory must not be accessible by other users\n";
   345	    chmod 0700, $self->backup_dir()
   346	        or die "cannot protect AppArmor rule backup directory: $!\n";
   347	    return;
   348	}
