   350	sub _read_local_include {
   351	    my ($self, $path) = @_;
   352	
   353	    my $local_root = $self->profile_dir() . '/local/';
   354	    index($path, $local_root) == 0 &&
   355	        substr($path, length($local_root)) =~ /\A[A-Za-z0-9][A-Za-z0-9._+@%:-]*\z/
   356	        or die "generated AppArmor local include is outside the approved policy root: $path\n";
   357	    return (q{}, 0) if !-e $path && !-l $path;
   358	
   359	    my @metadata = lstat($path);
   360	    @metadata && ($metadata[2] & 0170000) == 0100000 && !-l $path
   361	        or die "AppArmor local include must be a regular non-symlink file: $path\n";
   362	    $metadata[4] == $self->trusted_uid()
   363	        or die "AppArmor local include must be owned by the trusted account: $path\n";
   364	    ($metadata[2] & 0022) == 0
   365	        or die "AppArmor local include must not be group- or world-writable: $path\n";
   366	    $metadata[7] <= $self->maximum_include_bytes()
   367	        or die "AppArmor local include exceeds " . $self->maximum_include_bytes()
   368	            . " bytes: $path\n";
   369	
   370	    sysopen my $fh, $path, O_RDONLY | O_NOFOLLOW
   371	        or die "cannot read AppArmor local include: $path: $!\n";
   372	    binmode $fh, ':raw'
   373	        or die "cannot read AppArmor local include: $path: $!\n";
   374	    local $/;
   375	    my $content = <$fh>;
   376	    close $fh
   377	        or die "cannot close AppArmor local include: $path: $!\n";
   378	    return (defined($content) ? $content : q{}, 1);
   379	}
