   381	sub _merge_local_include {
   382	    my ($self, $content, $rules) = @_;
   383	
   384	    index($content, "\0") < 0
   385	        or die "AppArmor local include contains a NUL byte\n";
   386	    length($content) <= $self->maximum_include_bytes()
   387	        or die "AppArmor local include exceeds " . $self->maximum_include_bytes()
   388	            . " bytes\n";
   389	    my @lines = split /\n/, $content, -1;
   390	    pop @lines if @lines && $content =~ /\n\z/;
   391	    my (@begin, @end);
   392	    for my $index (0 .. $#lines) {
   393	        push @begin, $index if $lines[$index] eq $GENERATED_BEGIN;
   394	        push @end, $index if $lines[$index] eq $GENERATED_END;
   395	    }
   396	    (@begin == @end && @begin <= 1)
   397	        or die "AppArmor generated-rule marker block is malformed\n";
   398	    if (@begin) {
   399	        $begin[0] < $end[0]
   400	            or die "AppArmor generated-rule marker block is malformed\n";
   401	    }
   402	
   403	    my @manual_lines = @lines;
   404	    my @generated_rules;
   405	    if (@begin) {
   406	        for my $line (@lines[$begin[0] + 1 .. $end[0] - 1]) {
   407	            (my $normalized = $line) =~ s/\A\s+|\s+\z//g;
   408	            next if $normalized eq q{} || $normalized =~ /\A#/;
   409	            $normalized =~ /,\z/
   410	                or die "AppArmor generated-rule block contains an invalid rule\n";
   411	            push @generated_rules, $normalized;
   412	        }
   413	        splice @manual_lines, $begin[0], $end[0] - $begin[0] + 1;
   414	    }
   415	
   416	    my %selected = map { $_ => 1 } @generated_rules;
   417	    my @all_existing = (@manual_lines, @generated_rules);
   418	    for my $rule (@{$rules}) {
   419	        next if $self->_rule_is_subsumed($rule, \@all_existing);
   420	        $selected{$rule} = 1;
   421	        push @all_existing, $rule;
   422	    }
   423	    my @rendered_block = (
   424	        $GENERATED_BEGIN,
   425	        '# Generated only from validated DENIED records; edit outside this block.',
   426	        map { "  $_" } sort keys %selected,
   427	        $GENERATED_END,
   428	    );
   429	
   430	    while (@manual_lines && $manual_lines[-1] eq q{}) {
   431	        pop @manual_lines;
   432	    }
   433	    push @manual_lines, q{} if @manual_lines;
   434	    push @manual_lines, @rendered_block;
   435	    my $rendered = join("\n", @manual_lines) . "\n";
   436	    length($rendered) <= $self->maximum_include_bytes()
   437	        or die "generated AppArmor local include exceeds "
   438	            . $self->maximum_include_bytes() . " bytes\n";
   439	    return ($rendered, $rendered ne $content ? 1 : 0);
   440	}
