   442	sub _rule_is_subsumed {
   443	    my ($self, $candidate, $existing_lines) = @_;
   444	
   445	    (my $normalized_candidate = $candidate) =~ s/\A\s+|\s+\z//g;
   446	    my $candidate_file = $self->_parse_file_rule($normalized_candidate);
   447	    for my $line (@{$existing_lines}) {
   448	        (my $normalized = $line) =~ s/\A\s+|\s+\z//g;
   449	        next if $normalized eq q{} || $normalized =~ /\A#/;
   450	        return 1 if $normalized eq $normalized_candidate;
   451	        next if !$candidate_file;
   452	        my $existing_file = $self->_parse_file_rule($normalized);
   453	        next if !$existing_file;
   454	        next if $existing_file->{owner} ne $candidate_file->{owner};
   455	        next if $existing_file->{path} ne $candidate_file->{path};
   456	        my %existing_permissions =
   457	            map { $_ => 1 } split //, $existing_file->{permissions};
   458	        return 1
   459	            if !grep { !$existing_permissions{$_} }
   460	                split //, $candidate_file->{permissions};
   461	    }
   462	    return 0;
   463	}
