   465	sub _parse_file_rule {
   466	    my ($self, $rule) = @_;
   467	
   468	    return if $rule !~ /\A(owner\s+)?(.+?)\s+([rawkm]+),\z/;
   469	    return {
   470	        owner       => defined($1) ? 'owner' : q{},
   471	        path        => $2,
   472	        permissions => $3,
   473	    };
   474	}
