   519	            chmod 0600, $target
   520	                or die "cannot protect staged AppArmor source: $!\n";
   521	        }
   522	        else {
   523	            symlink $source, $target
   524	                or die "cannot link AppArmor validation dependency: $source: $!\n";
   525	        }
   526	    }
   527	    closedir $profile_dh
   528	        or die "cannot close AppArmor profile directory during validation: $!\n";
   529	
   530	    my $actual_local = $self->profile_dir() . '/local';
   531	    opendir my $local_dh, $actual_local
   532	        or die "cannot read AppArmor local policy directory during validation: $!\n";
   533	    my $local_entries = 0;
   534	    while (my $name = readdir $local_dh) {
   535	        next if $name eq q{.} || $name eq q{..};
   536	        ++$local_entries;
   537	        $local_entries <= $self->maximum_local_entries()
   538	            or die "AppArmor local policy directory contains too many entries\n";
   539	        next if $name eq $group->{local_name};
   540	        next if $name !~ /\A[A-Za-z0-9][A-Za-z0-9._+@%:-]*\z/;
   541	        symlink "$actual_local/$name", "$overlay_local/$name"
   542	            or die "cannot link AppArmor local validation dependency: $name: $!\n";
   543	    }
   544	    closedir $local_dh
   545	        or die "cannot close AppArmor local policy directory during validation: $!\n";
   546	    copy($candidate_path, "$overlay_local/$group->{local_name}")
   547	        or die "cannot stage generated AppArmor local policy for validation: $!\n";
   548	    chmod 0600, "$overlay_local/$group->{local_name}"
   549	        or die "cannot protect generated AppArmor validation policy: $!\n";
   550	
   551	    my $parser = $self->command()->require_executable('apparmor_parser');
   552	    my $status = $self->command()->run(
   553	        $parser,
   554	        '--config-file', $self->parser_config(),
   555	        '-q', '-Q', '-K', '-T',
   556	        '-I', $overlay,
   557	        '--base', $overlay,
   558	        "$overlay/$safe_source",
