   575	        or die "cannot create AppArmor local policy transaction: $!\n";
   576	    copy($source, $temporary)
   577	        or die "cannot stage AppArmor local policy transaction: $!\n";
   578	    chmod 0644, $temporary
   579	        or die "cannot protect AppArmor local policy transaction: $!\n";
   580	    rename $temporary, $target
   581	        or die "cannot publish AppArmor local policy transaction: $!\n";
   582	    return;
