   110	);
   111	
   112	has renderer => (
   113	    is      => 'ro',
   114	    isa     => Object,
   115	    default => sub { LabwcSecurityAction::AppArmor::RuleRenderer->new() },
   116	);
   117	
   118	sub run {
   119	    my ($self, $confirmation) = @_;
   120	
   121	    defined($confirmation) &&
   122	        $confirmation eq 'confirmed-apparmor-rule-generation'
   123	        or die "AppArmor rule generation requires explicit confirmation\n";
   124	    my ($records, $parse_rejections) =
   125	        $self->audit_log()->read_denials($self->event_log());
   126	    my $index = $self->profile_index()->build();
   127	
   128	    my (@unresolved, %groups, $candidate_count);
   129	    push @unresolved, @{$parse_rejections};
   130	    for my $record (@{$records}) {
   131	        my $fields = $record->{fields};
   132	        my $profile = $fields->{profile};
   133	        if ($profile eq 'unconfined' || $profile =~ /\Aunconfined(?:\/|\z)/) {
   134	            push @unresolved, $self->_unresolved(
   135	                $record,
   136	                'unconfined audit records cannot receive AppArmor policy rules',
   137	            );
   138	            next;
   139	        }
   140	
   141	        my $target = $self->profile_index()->resolve($index, $profile);
   142	        if (!$target) {
   143	            push @unresolved, $self->_unresolved(
   144	                $record,
   145	                'profile label cannot be mapped to an installed AppArmor source',
   146	            );
   147	            next;
   148	        }
   149	        if (!defined($target->{local_name}) ||
   150	            $target->{local_name} !~ /\A[A-Za-z0-9][A-Za-z0-9._+@%:-]*\z/) {
   151	            push @unresolved, $self->_unresolved(
   152	                $record,
   153	                'profile has no unambiguous local include for generated rules',
   154	            );
   155	            next;
   156	        }
   157	
   158	        my $rendered = $self->renderer()->render($record);
   159	        if (!$rendered->{ok}) {
   160	            push @unresolved, $self->_unresolved(
   161	                $record,
   162	                $rendered->{reason},
   163	            );
   164	            next;
   165	        }
   166	
   167	        my $group = $groups{$target->{local_path}} //= {
   168	            local_name  => $target->{local_name},
   169	            local_path  => $target->{local_path},
   170	            rules       => {},
   171	            source_name => $target->{source_name},
   172	            source_path => $target->{source_path},
   173	        };
   174	        $group->{source_path} eq $target->{source_path}
   175	            or die "generated AppArmor local include maps to multiple profile sources: "
   176	                . $target->{local_path} . "\n";
   177	        if (!$group->{rules}->{ $rendered->{rule} }) {
   178	            ++$candidate_count;
   179	            $candidate_count <= $self->maximum_rules()
   180	                or die "AppArmor rule generation produced more than "
   181	                    . $self->maximum_rules() . " candidate rules\n";
   182	            $group->{rules}->{ $rendered->{rule} } = {
   183	                count   => $record->{count},
   184	                kind    => $rendered->{kind},
   185	                profile => $profile,
   186	            };
   187	        }
   188	        else {
   189	            $group->{rules}->{ $rendered->{rule} }->{count} +=
   190	                $record->{count};
   191	        }
   192	    }
   193	
   194	    if (!keys(%groups)) {
   195	        $self->_report_unresolved(\@unresolved);
   196	        print "No safe AppArmor rules were generated.\n";
   197	        return 2;
   198	    }
   199	
   200	    $self->_prepare_backup_dir();
   201	    my $batch = tempdir(
   202	        'generate.XXXXXX',
   203	        DIR     => $self->backup_dir(),
   204	        CLEANUP => 0,
   205	    );
   206	    chmod 0700, $batch
   207	        or die "cannot protect AppArmor rule generation workspace: $!\n";
   208	    my (@states, @changed_groups);
   209	    my $status = eval {
   210	        for my $local_path (sort keys %groups) {
   211	            my $group = $groups{$local_path};
   212	            my ($existing, $existed) = $self->_read_local_include($local_path);
   213	            my ($candidate, $changed) = $self->_merge_local_include(
   214	                $existing,
   215	                [sort keys %{ $group->{rules} }],
   216	            );
   217	            next if !$changed;
   218	
   219	            my $candidate_dir = "$batch/candidates";
   220	            make_path($candidate_dir, { mode => 0700 }) if !-d $candidate_dir;
   221	            my $candidate_path = "$candidate_dir/$group->{local_name}";
   222	            $self->_write_private_file($candidate_path, $candidate);
   223	            $self->_validate_candidate($group, $candidate_path, $batch);
   224	
   225	            my $backup_path;
   226	            if ($existed) {
   227	                my $backup_root = "$batch/previous";
   228	                make_path($backup_root, { mode => 0700 }) if !-d $backup_root;
   229	                $backup_path = "$backup_root/$group->{local_name}";
   230	                copy($local_path, $backup_path)
   231	                    or die "cannot back up AppArmor local policy: $local_path: $!\n";
   232	                chmod 0600, $backup_path
   233	                    or die "cannot protect AppArmor local policy backup: $!\n";
   234	            }
   235	            push @states, {
   236	                backup_path   => $backup_path,
   237	                candidate_path => $candidate_path,
   238	                existed       => $existed,
   239	                group         => $group,
   240	                published     => 0,
   241	            };
   242	            push @changed_groups, $group;
   243	        }
   244	
   245	        for my $state (@states) {
   246	            $self->_publish_atomic(
   247	                $state->{candidate_path},
   248	                $state->{group}->{local_path},
   249	            );
   250	            $state->{published} = 1;
   251	        }
   252	        if ($self->reload_profiles()) {
   253	            my %reloaded;
   254	            for my $group (@changed_groups) {
   255	                next if $reloaded{ $group->{source_path} }++;
   256	                $self->_reload_source($group);
   257	            }
   258	        }
   259	        return 1;
   260	    };
   261	    my $error = $@;
   262	    if (!$status) {
   263	        my $rollback_error = $self->_rollback(\@states, \@changed_groups);
   264	        remove_tree($batch, { safe => 1 });
   265	        $error ||= "AppArmor rule generation failed\n";
   266	        $error =~ s/\s+\z//;
   267	        $error .= "; rollback warning: $rollback_error"
   268	            if defined($rollback_error) && $rollback_error ne q{};
   269	        die "$error\n";
   270	    }
   271	
   272	    remove_tree($batch, { safe => 1 });
   273	    my $rule_total = 0;
   274	    $rule_total += scalar(keys %{ $_->{rules} }) for @changed_groups;
   275	    if ($rule_total) {
   276	        printf "Applied %d unique AppArmor rule%s across %d local include%s.\n",
   277	            $rule_total,
   278	            $rule_total == 1 ? q{} : 's',
   279	            scalar(@changed_groups),
   280	            @changed_groups == 1 ? q{} : 's';
   281	    }
   282	    else {
   283	        print "Every safe generated AppArmor rule was already present or subsumed.\n";
   284	    }
   285	    $self->_report_unresolved(\@unresolved);
   286	    return 0;
   287	}
   288	
   289	sub _unresolved {
   290	    my ($self, $record, $reason) = @_;
   291	
   292	    return {
   293	        count       => $record->{count} // 1,
   294	        line_number => $record->{line_number},
   295	        profile     => $record->{fields}->{profile} // 'unknown',
   296	        reason      => $reason,
   297	    };
   298	}
   299	
   300	sub _report_unresolved {
   301	    my ($self, $unresolved) = @_;
   302	
   303	    return if !@{$unresolved};
   304	    printf "Skipped %d unresolved or unsafe AppArmor denial type%s:\n",
   305	        scalar(@{$unresolved}),
   306	        @{$unresolved} == 1 ? q{} : 's';
   307	    my $shown = 0;
   308	    for my $entry (@{$unresolved}) {
   309	        last if $shown >= 100;
   310	        my $profile = $entry->{profile} // 'unknown';
   311	        $profile =~ s/[\r\n]/?/g;
   312	        my $reason = $entry->{reason} // 'unspecified reason';
   313	        $reason =~ s/[\r\n]+/ /g;
   314	        printf "  line=%s count=%s profile=%s reason=%s\n",
   315	            $entry->{line_number} // '?',
   316	            $entry->{count} // 1,
   317	            $profile,
   318	            $reason;
   319	        ++$shown;
   320	    }
   321	    print "  additional unresolved records were omitted from this display\n"
   322	        if @{$unresolved} > $shown;
   323	    return;
   324	}
