   350	sub _read_local_include {
   351	    my ($self, $path) = @_;
   352	
   353	    my $local_root = $self->profile_dir() . '/local/';
   354	    index($path, $local_root) == 0 &&
   355	        substr($path, length($local_root)) =~ /\A[A-Za-z0-9][A-Za-z0-9._+@%:-]*\z/
   356	        or die "generated AppArmor local include is outside the approved policy root: $path\n";
   357	    return (q{}, 0) if !-e $path && !-l $path;
   358	
   359	    my @metadata = lstat($path);
   360	    @metadata && ($metadata[2] & 0170000) == 0100000 && !-l $path
--- RuleGenerator.pm 361-700 ---
   361	        or die "AppArmor local include must be a regular non-symlink file: $path\n";
   362	    $metadata[4] == $self->trusted_uid()
   363	        or die "AppArmor local include must be owned by the trusted account: $path\n";
   364	    ($metadata[2] & 0022) == 0
   365	        or die "AppArmor local include must not be group- or world-writable: $path\n";
   366	    $metadata[7] <= $self->maximum_include_bytes()
   367	        or die "AppArmor local include exceeds " . $self->maximum_include_bytes()
   368	            . " bytes: $path\n";
   369	
   370	    sysopen my $fh, $path, O_RDONLY | O_NOFOLLOW
   371	        or die "cannot read AppArmor local include: $path: $!\n";
   372	    binmode $fh, ':raw'
   373	        or die "cannot read AppArmor local include: $path: $!\n";
   374	    local $/;
   375	    my $content = <$fh>;
   376	    close $fh
   377	        or die "cannot close AppArmor local include: $path: $!\n";
   378	    return (defined($content) ? $content : q{}, 1);
   379	}
   380	
   381	sub _merge_local_include {
   382	    my ($self, $content, $rules) = @_;
   383	
   384	    index($content, "\0") < 0
   385	        or die "AppArmor local include contains a NUL byte\n";
   386	    length($content) <= $self->maximum_include_bytes()
   387	        or die "AppArmor local include exceeds " . $self->maximum_include_bytes()
   388	            . " bytes\n";
   389	    my @lines = split /\n/, $content, -1;
   390	    pop @lines if @lines && $content =~ /\n\z/;
   391	    my (@begin, @end);
   392	    for my $index (0 .. $#lines) {
   393	        push @begin, $index if $lines[$index] eq $GENERATED_BEGIN;
   394	        push @end, $index if $lines[$index] eq $GENERATED_END;
   395	    }
   396	    (@begin == @end && @begin <= 1)
   397	        or die "AppArmor generated-rule marker block is malformed\n";
   398	    if (@begin) {
   399	        $begin[0] < $end[0]
   400	            or die "AppArmor generated-rule marker block is malformed\n";
   401	    }
   402	
   403	    my @manual_lines = @lines;
   404	    my @generated_rules;
   405	    if (@begin) {
   406	        for my $line (@lines[$begin[0] + 1 .. $end[0] - 1]) {
   407	            (my $normalized = $line) =~ s/\A\s+|\s+\z//g;
   408	            next if $normalized eq q{} || $normalized =~ /\A#/;
   409	            $normalized =~ /,\z/
   410	                or die "AppArmor generated-rule block contains an invalid rule\n";
   411	            push @generated_rules, $normalized;
   412	        }
   413	        splice @manual_lines, $begin[0], $end[0] - $begin[0] + 1;
   414	    }
   415	
   416	    my %selected = map { $_ => 1 } @generated_rules;
   417	    my @all_existing = (@manual_lines, @generated_rules);
   418	    for my $rule (@{$rules}) {
   419	        next if $self->_rule_is_subsumed($rule, \@all_existing);
   420	        $selected{$rule} = 1;
   421	        push @all_existing, $rule;
   422	    }
   423	    my @rendered_block = (
   424	        $GENERATED_BEGIN,
   425	        '# Generated only from validated DENIED records; edit outside this block.',
   426	        map { "  $_" } sort keys %selected,
   427	        $GENERATED_END,
   428	    );
   429	
   430	    while (@manual_lines && $manual_lines[-1] eq q{}) {
   431	        pop @manual_lines;
   432	    }
   433	    push @manual_lines, q{} if @manual_lines;
   434	    push @manual_lines, @rendered_block;
   435	    my $rendered = join("\n", @manual_lines) . "\n";
   436	    length($rendered) <= $self->maximum_include_bytes()
   437	        or die "generated AppArmor local include exceeds "
   438	            . $self->maximum_include_bytes() . " bytes\n";
   439	    return ($rendered, $rendered ne $content ? 1 : 0);
   440	}
   441	
   442	sub _rule_is_subsumed {
   443	    my ($self, $candidate, $existing_lines) = @_;
   444	
   445	    (my $normalized_candidate = $candidate) =~ s/\A\s+|\s+\z//g;
   446	    my $candidate_file = $self->_parse_file_rule($normalized_candidate);
   447	    for my $line (@{$existing_lines}) {
   448	        (my $normalized = $line) =~ s/\A\s+|\s+\z//g;
   449	        next if $normalized eq q{} || $normalized =~ /\A#/;
   450	        return 1 if $normalized eq $normalized_candidate;
   451	        next if !$candidate_file;
   452	        my $existing_file = $self->_parse_file_rule($normalized);
   453	        next if !$existing_file;
   454	        next if $existing_file->{owner} ne $candidate_file->{owner};
   455	        next if $existing_file->{path} ne $candidate_file->{path};
   456	        my %existing_permissions =
   457	            map { $_ => 1 } split //, $existing_file->{permissions};
   458	        return 1
   459	            if !grep { !$existing_permissions{$_} }
   460	                split //, $candidate_file->{permissions};
   461	    }
   462	    return 0;
   463	}
   464	
   465	sub _parse_file_rule {
   466	    my ($self, $rule) = @_;
   467	
   468	    return if $rule !~ /\A(owner\s+)?(.+?)\s+([rawkm]+),\z/;
   469	    return {
   470	        owner       => defined($1) ? 'owner' : q{},
   471	        path        => $2,
   472	        permissions => $3,
   473	    };
   474	}
   475	
   476	sub _write_private_file {
   477	    my ($self, $path, $content) = @_;
   478	
   479	    open my $fh, '>:raw', $path
   480	        or die "cannot write AppArmor rule candidate: $path: $!\n";
   481	    print {$fh} $content
   482	        or die "cannot write AppArmor rule candidate: $path: $!\n";
   483	    close $fh
   484	        or die "cannot close AppArmor rule candidate: $path: $!\n";
   485	    chmod 0600, $path
   486	        or die "cannot protect AppArmor rule candidate: $path: $!\n";
   487	    return;
   488	}
