   585	sub _reload_source {
   586	    my ($self, $group) = @_;
   587	
   588	    my $disable_link =
   589	        $self->profile_dir() . "/disable/$group->{source_name}";
   590	    if (-l $disable_link &&
   591	        defined(readlink($disable_link)) &&
   592	        readlink($disable_link) eq $group->{source_path}) {
   593	        print "Updated disabled AppArmor source without loading it: "
   594	            . $group->{source_name} . "\n";
   595	        return;
   596	    }
   597	    my $parser = $self->command()->require_executable('apparmor_parser');
   598	    my $status = $self->command()->run(
   599	        $parser,
   600	        '--config-file', $self->parser_config(),
   601	        '-q', '-r',
   602	        '-I', $self->profile_dir(),
   603	        '--base', $self->profile_dir(),
   604	        $group->{source_path},
   605	    );
   606	    $status == 0
   607	        or die "cannot reload AppArmor source after generated rule update: "
   608	            . $group->{source_name} . "\n";
   609	    return;
   610	}
   611	
   612	sub _rollback {
   613	    my ($self, $states, $changed_groups) = @_;
   614	
   615	    my @errors;
   616	    for my $state (reverse @{$states}) {
   617	        next if !$state->{published};
   618	        my $target = $state->{group}->{local_path};
   619	        if ($state->{existed}) {
   620	            eval { $self->_publish_atomic($state->{backup_path}, $target); 1 }
   621	                or push @errors, "cannot restore $target";
   622	        }
   623	        elsif (-e $target || -l $target) {
   624	            unlink $target
   625	                or push @errors, "cannot remove newly generated $target";
   626	        }
   627	    }
   628	    if ($self->reload_profiles()) {
   629	        my %restored;
   630	        for my $group (@{$changed_groups}) {
   631	            next if $restored{ $group->{source_path} }++;
   632	            eval { $self->_reload_source($group); 1 }
   633	                or push @errors, "cannot reload restored $group->{source_name}";
