--- managed modes config first 90 ---
     1	# Managed by unattended-installer.
     2	#
     3	# Format:
     4	#   MODE PRESENCE PROFILE_FILE EXECUTABLE_PROBE
     5	#
     6	# MODE is enforce, complain, or disable.
     7	# PRESENCE is required, optional, or if-executable.
     8	# PROFILE_FILE is relative to /etc/apparmor.d and must not contain slashes.
     9	# EXECUTABLE_PROBE is "-" unless PRESENCE is if-executable.
    10	#
    11	# Repository-owned desktop application profiles use the managed least-privilege
    12	# abstractions and default to enforce mode. Desktop host profiles may select
    13	# enforce or complain for this set through DESKTOP_APPARMOR_STATE during target
    14	# staging. Selected package-owned Code and browser profiles follow the same
    15	# desktop state because they use repository-managed local rules. PowerShell
    16	# remains in complain mode because it is an administrative shell intended to
    17	# execute arbitrary host commands. crun and Timeshift use complete
    18	# repository-owned attachments and are enforced independently of the desktop
    19	# profile state. Tailscale is enforced after review of its fresh-install daemon
    20	# and bootstrap activity. Other service, browser, container, and vendor
    21	# profiles remain in complain mode until their workload-specific ALLOWED events
    22	# have been reviewed.
    23	#
    24	# apparmor-managed-modes reconciles only this declared profile policy. Kernel
    25	# selection, kernel configuration, boot command-line flags, LSM ordering, and
    26	# AppArmor feature availability are preconfigured by the installer and are not
    27	# probed or revalidated by the mode helper.
    28	
    29	# Repository-managed desktop application profiles.
    30	enforce required managed-desktop-wrappers -
    31	enforce required whisper-local-transcription -
    32	enforce required usr.bin.totem -
    33	enforce required usr.bin.dbeaver-ce -
    34	enforce required usr.bin.spotify -
    35	enforce required usr.bin.sqlitebrowser -
    36	complain required usr.bin.pwsh -
    37	enforce required usr.bin.retroarch -
    38	enforce required usr.bin.qbittorrent -
    39	enforce required usr.bin.telegram-desktop -
    40	enforce required usr.bin.keepassxc -
    41	enforce required usr.bin.zoom -
    42	enforce required opt.Bitwarden.bitwarden -
    43	enforce required opt.Filen.Filen -
    44	enforce required opt.postman.app.Postman -
    45	enforce required opt.ledger-live.AppRun -
    46	enforce required opt.tuta-mail.AppRun -
    47	enforce required Discord -
    48	enforce required obsidian -
    49	enforce required sleek -
    50	
    51	# Repository-managed privileged runtime profiles.
    52	enforce required crun -
    53	enforce required timeshift -
    54	
    55	# Repository-managed service compatibility profiles.
    56	complain required usr.sbin.apt-cacher-ng -
    57	complain required usr.sbin.avahi-daemon -
    58	enforce if-executable usr.sbin.tailscaled /usr/sbin/tailscaled
    59	
    60	# Package-owned desktop profiles selected by this repository. Their vendor
    61	# attachment files are retained, least-privilege rules are supplied through
    62	# local includes, and the mode helper removes unconfined/default-allow flags.
    63	enforce if-executable code /usr/bin/code
    64	enforce if-executable chromium /usr/bin/chromium
    65	disable optional msedge -
    66	disable optional opt.microsoft.msedge.microsoft-edge -
    67	enforce if-executable microsoft-edge-stable /usr/bin/microsoft-edge-stable
    68	enforce if-executable mullvad-browser /usr/bin/mullvad-browser
    69	enforce if-executable vivaldi-stable /usr/bin/vivaldi-stable
    70	enforce if-executable vivaldi-bin /usr/bin/vivaldi-stable
    71	
    72	# Package-owned desktop profiles that otherwise load unconfined.
    73	# The installer copies local/managed-desktop-application to each matching
    74	# local/<profile> include before changing these profiles to complain mode.
    75	complain if-executable 1password /opt/1Password/1password
