    83	complain if-executable opera /usr/bin/opera
    84	complain if-executable qutebrowser /usr/bin/qutebrowser
    85	complain if-executable signal-desktop /usr/bin/signal-desktop
    86	complain if-executable slack /usr/bin/slack
    87	complain if-executable steam /usr/bin/steam
